-- Check how many signals are in signaldecoding vs signals table
SELECT COUNT(*) FROM signals;
SELECT COUNT(*) FROM signaldecoding;

-- Let me check if signals table has any priority or confidence related columns
SELECT column_name FROM information_schema.columns 
WHERE table_name = 'signals' AND (column_name ILIKE '%prio%' OR column_name ILIKE '%conf%' OR column_name ILIKE '%score%');

-- Let me check if there are signals without researchprocess or signaldecoding entries
SELECT COUNT(*) as total_signals FROM signals;
SELECT COUNT(DISTINCT s.signalregistry) as with_rp FROM signals s JOIN researchprocess rp ON s.signalregistry = rp.signalref;
SELECT COUNT(DISTINCT s.signalregistry) as with_sd FROM signals s JOIN signaldecoding sd ON s.signalregistry = sd.signalref;
